import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import {CpuChart} from './CpuChart';
import {STEP_MS, sampleCpu} from './useCpuStream';

export function run(strict: boolean) {
    const N = 43200;
    const end = Math.floor(Date.now() / STEP_MS) * STEP_MS;
    let timeline = Array.from({length: N}, (_, i) => end - (N - 1 - i) * STEP_MS);
    let values = timeline.map(sampleCpu);
    const host = document.createElement('div');
    host.style.width = '800px';
    document.body.appendChild(host);
    const root = ReactDOM.createRoot(host);
    const render = () => {
        const el = (
            <ThemeProvider theme="light">
                <CpuChart timeline={timeline} values={values} />
            </ThemeProvider>
        );
        root.render(strict ? <React.StrictMode>{el}</React.StrictMode> : el);
    };
    const tick = (k: number) => {
        const last = timeline[timeline.length - 1];
        const t = timeline.slice(k);
        const v = values.slice(k);
        for (let i = 1; i <= k; i++) {
            t.push(last + i * STEP_MS);
            v.push(sampleCpu(last + i * STEP_MS));
        }
        timeline = t;
        values = v;
        render();
    };
    return {host, root, render, tick};
}
